//! PRIVATE_PROJECT PRIVATE_REPORT GAME_ROOT EXPLICIT_PACKAGES...
use external_cas_assets::Catalog;
use external_cas_character::{assemble_character,CharacterOptions};
use external_cas_material::resolve_character_material_inputs;
use external_cas_scene::GameInstallScope;
use external_cas_tray::{reopen_project,ProjectDraft};
use sha2::{Digest,Sha256};
use std::{path::PathBuf,sync::atomic::AtomicBool,io::Write};
fn compare_primary(input:&external_cas_material::CharacterMaterialInputs,dll:&std::path::Path)->Result<serde_json::Value,Box<dyn std::error::Error>>{
    use std::process::{Command,Stdio};
    let materials=input.parts.iter().flat_map(|p|&p.meshes).filter_map(|m|m.material.as_ref().map(|v|(m,v))).collect::<Vec<_>>();
    let request=serde_json::json!({"materials":materials.iter().map(|(mesh,material)|serde_json::json!({"key":mesh.key.to_string(),"hex":material.original.iter().map(|b|format!("{b:02x}")).collect::<String>()})).collect::<Vec<_>>()});
    let mut child=Command::new("dotnet").arg(dll).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn()?;child.stdin.take().unwrap().write_all(&serde_json::to_vec(&request)?)?;let output=child.wait_with_output()?;if !output.status.success(){return Err(format!("MTNF primary reader failed: {}",String::from_utf8_lossy(&output.stderr)).into())}
    let reference:serde_json::Value=serde_json::from_slice(&output.stdout)?;let references=reference.as_array().ok_or("Primary material array")?;assert_eq!(references.len(),materials.len());let mut parameters=0usize;let mut words=0usize;
    for ((mesh,material),reference) in materials.iter().zip(references){
        assert_eq!(reference["key"].as_str(),Some(mesh.key.to_string().as_str()));assert_eq!(reference["consumed"].as_u64(),Some(material.original.len()as u64));let entries=reference["parameters"].as_array().unwrap();assert_eq!(entries.len(),material.parameters.len());
        for (actual,expected) in material.parameters.iter().zip(entries){assert_eq!(expected["hash"].as_u64(),Some(actual.hash as u64));assert_eq!(expected["data_type"].as_u64(),Some(actual.data_type as u64));assert_eq!(expected["count"].as_u64(),Some(actual.count as u64));assert_eq!(expected["offset"].as_u64(),Some(actual.offset as u64));let expected=expected["words"].as_array().unwrap().iter().map(|w|w.as_u64().unwrap()as u32).collect::<Vec<_>>();assert_eq!(expected,actual.words);parameters+=1;words+=actual.words.len();}
        let roundtrip=reference["roundtrip_words"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u32).collect::<Vec<_>>();let original=material.original.chunks_exact(4).map(|b|u32::from_le_bytes(b.try_into().unwrap())).collect::<Vec<_>>();assert_eq!(roundtrip,original);
        for (hash,field) in [(0x6e56548a,"normal_index"),(0xf303d152,"emission_index")]{let index=material.unique_parameter(hash)?.map(|p|p.words[0]as i32).unwrap_or(-1);assert_eq!(reference[field].as_i64(),Some(index as i64));}
    }
    Ok(serde_json::json!({"materials":materials.len(),"parameters":parameters,"raw_value_words":words,"headers_words_and_roundtrip_exact":true,"normal_emission_getters_exact":true,"reader":"Unchanged pinned SimRipper GEOM.MTNF"}))
}
fn main()->Result<(),Box<dyn std::error::Error>>{
    let args:Vec<_>=std::env::args_os().skip(1).map(PathBuf::from).collect();if args.len()<4{return Err("project exclusive-report game-root packages...".into())}
    if args[1].exists(){return Err("Exclusive new report required".into())}
    let project=reopen_project(&args[0])?;let sims=ProjectDraft::from_project(&project)?.appearance()?;let cancel=AtomicBool::new(false);
    let catalog=Catalog::scan_roots(&args[3..],&cancel,|_|{})?;let scope=GameInstallScope::discover(&args[2])?;let policy=scope.prepare(&catalog)?;let plan=assemble_character(sims.first().ok_or("No actual Sim")?,&catalog,Some(&policy),&CharacterOptions::default())?;
    let start=std::time::Instant::now();let input=resolve_character_material_inputs(&plan,&catalog,Some(&policy),&cancel,|_|{})?;let elapsed=start.elapsed().as_millis();
    let primary=if let Some(dll)=std::env::var_os("CAS_MTNF_ORACLE"){compare_primary(&input,&PathBuf::from(dll))?}else{serde_json::Value::Null};
    let mut planes=0;let mut decoded=0;let mut roles=std::collections::BTreeMap::<String,usize>::new();let mut shared=std::collections::BTreeMap::new();
    for part in &input.parts{for plane in &part.planes{planes+=1;*roles.entry(plane.role.clone()).or_default()+=1;if let Some(image)=&plane.decoded{decoded+=1;if let Some(old)=shared.insert(image.source.key,image){assert!(std::sync::Arc::ptr_eq(old,image),"Repeated native full TGI was decoded into duplicate planes")}}}}
    scope.revalidate()?;for source in &catalog.packages{source.revalidate(&cancel)?;}if !project.check_source_conflicts().is_empty(){return Err("Original Tray source changed".into())}
    let report=serde_json::json!({"schema":1,"parts":input.parts.len(),"planes":planes,"decoded":decoded,"unique_decoded_planes":shared.len(),"decoded_bytes":input.decoded_bytes,"roles":roles,"elapsed_ms":elapsed,"parts_detail":input.parts.iter().map(|p|serde_json::json!({"part":p.part_index,"body_type":p.body_type,"texture_space":p.texture_space,"composition_method":p.composition_method,"sort_layer":p.sort_layer,"packed_color_shift":p.packed_color_shift.map(|v|format!("{v:016X}")),"mesh_shader_hashes":p.mesh_shader_hashes.iter().map(|v|format!("{v:08X}")).collect::<Vec<_>>(),"planes":p.planes.iter().map(|i|serde_json::json!({"role":i.role,"declared_key":i.declared_key.to_string(),"key":i.source.key.to_string(),"payload_sha256":i.source.payload_sha256.map(|h|h.iter().map(|v|format!("{v:02x}")).collect::<String>()),"decoded":i.decoded.is_some(),"width":i.decoded.as_ref().map(|d|d.pixels.width),"height":i.decoded.as_ref().map(|d|d.pixels.height),"rgba_sha256":i.decoded.as_ref().map(|d|format!("{:x}",Sha256::digest(&d.pixels.rgba))),"alpha_sha256":i.decoded.as_ref().map(|d|format!("{:x}",Sha256::digest(d.pixels.rgba.chunks_exact(4).map(|p|p[3]).collect::<Vec<_>>()))),"blue_sha256":i.decoded.as_ref().map(|d|format!("{:x}",Sha256::digest(d.pixels.rgba.chunks_exact(4).map(|p|p[2]).collect::<Vec<_>>()))),"auxiliary_retained":i.decoded.as_ref().map(|d|d.uninterpreted_auxiliary_streams),"issues":i.issues})).collect::<Vec<_>>(),"issues":p.issues})).collect::<Vec<_>>(),"unresolved_global_bindings":input.unresolved_global_bindings.iter().map(|b|serde_json::json!({"name":b.parameter_name,"hash":format!("{:08X}",b.parameter_hash),"sampling":b.sampling_contract,"reason":b.reason})).collect::<Vec<_>>(),"issues":input.issues,"native_qualified":input.native_qualified,"source_conflicts":0,"originals_written":false,"game_contacted":false});
    let mut report=report;
    report["primary_mtnf_comparison"]=primary;
    report["native_globals"]=serde_json::json!({"ambient":input.globals.ambient.as_ref().map(|v|serde_json::json!({"context":v.context,"key":v.image.source.key.to_string(),"width":v.image.pixels.width,"height":v.image.pixels.height,"rgba_sha256":format!("{:x}",Sha256::digest(&v.image.pixels.rgba))})),"tone_lookup":input.globals.tone_lookup.as_ref().map(|v|serde_json::json!({"tone_key":v.source.key.to_string(),"packed_input":format!("{:08X}",v.lookup.packed_input),"width":v.lookup.width,"height":v.lookup.height,"bgra_sha256":format!("{:x}",Sha256::digest(&v.lookup.bgra)),"dxgi_resource_format":v.dxgi_resource_format})),"issues":input.globals.issues});
    report["mesh_materials"]=serde_json::json!(input.parts.iter().flat_map(|part|part.meshes.iter().map(move|mesh|(part,mesh))).map(|(part,mesh)|serde_json::json!({"part":part.part_index,"mesh":mesh.mesh_index,"key":mesh.key.to_string(),"shader":mesh.shader_hash.map(|s|format!("{s:08X}")),"material_sha256":mesh.material.as_ref().map(|m|format!("{:x}",Sha256::digest(&m.original))),"parameters":mesh.material.as_ref().map(|m|m.parameters.iter().map(|p|serde_json::json!({"hash":format!("{:08X}",p.hash),"type":p.data_type,"count":p.count,"offset":p.offset,"words":p.words})).collect::<Vec<_>>()),"reference_normal_key":mesh.reference_normal_key.map(|k|k.to_string()),"casp_normal_key":part.planes.iter().find(|p|p.role=="normal").map(|p|p.declared_key.to_string()),"reference_emission_key":mesh.reference_emission_key.map(|k|k.to_string()),"issues":mesh.issues})).collect::<Vec<_>>());
    let mut file=std::fs::OpenOptions::new().write(true).create_new(true).open(&args[1])?;file.write_all(&serde_json::to_vec_pretty(&report)?)?;file.sync_all()?;println!("parts={} declared_planes={planes} decoded={decoded} unique={} decoded_bytes={} originals_unchanged=true",input.parts.len(),shared.len(),input.decoded_bytes);Ok(())
}
